  "transform_code": "def transform(df: pd.DataFrame) -> pd.DataFrame:\n    # Work on a copy\n    df = df.copy()\n\n    # 1) Construct Approved outcome (1 = accepted, 0 = denied).\n    # Prefer using 'Unnamed: 0' when present (schema suggests it encodes acceptance),\n    # otherwise try to infer from 'mortgage_credit' which in schema is described as 1=denied,0=accepted.\n    if 'Unnamed: 0' in df.columns:\n        df['Approved'] = pd.to_numeric(df['Unnamed: 0'], errors='coerce').astype('Float64')\n    elif 'mortgage_credit' in df.columns:\n        # mortgage_credit described as 1 if denied, 0 if accepted -> invert\n        df['Approved'] = pd.to_numeric(df['mortgage_credit'], errors='coerce').apply(lambda x: 1 if x == 0 else (0 if x == 1 else np.nan)).astype('Float64')\n    else:\n        # If neither column exists, raise informative error by creating empty Approved column\n        df['Approved'] = np.nan\n\n    # 2) Construct Female indicator from 'consumer_credit' (explicitly documented as female indicator) or fallback to 'female'\n    if 'consumer_credit' in df.columns:\n        df['Female'] = pd.to_numeric(df['consumer_credit'], errors='coerce').apply(lambda x: 1 if x == 1 else (0 if x == 0 else np.nan)).astype('Float64')\n    elif 'female' in df.columns:\n        # 'female' in schema seems continuous; treat values >= 0.5 as female when necessary\n        df['Female'] = pd.to_numeric(df['female'], errors='coerce').apply(lambda x: 1 if x >= 0.5 else (0 if x < 0.5 else np.nan)).astype('Float64')\n    else:\n        df['Female'] = np.nan\n\n    # 3) Ensure control columns are present and numeric; convert if present\n    control_cols = ['bad_history', 'mortgage_credit', 'loan_to_value', 'denied_PMI', 'self_employed', 'married', 'housing_expense_ratio', 'PI_ratio']\n    present_controls = [c for c in control_cols if c in df.columns]\n\n    for c in present_controls:\n        df[c] = pd.to_numeric(df[c], errors='coerce').astype('Float64')\n\n    # 4) Keep only rows with non-missing values for outcome, IV, and controls used in the model\n    required_cols = ['Approved', 'Female'] + present_controls\n    df = df.dropna(subset=required_cols).reset_index(drop=True)\n\n    # 5) Cast binary columns to integer dtype (0/1)\n    df['Approved'] = df['Approved'].astype(int)\n    df['Female'] = df['Female'].astype(int)\n    for c in present_controls:\n        # If control is clearly binary (unique values subset of {0,1}), cast to int for clarity\n        unique_vals = pd.unique(df[c].dropna())\n        if set(unique_vals).issubset({0, 1}):\n            df[c] = df[c].astype(int)\n\n    # 6) Final dataframe includes only the variables used in the model (keeps present controls)\n    final_cols = ['Approved', 'Female'] + present_controls\n    df = df[final_cols]\n\n    return df\n",
  "m_code": "def model(df: pd.DataFrame) -> Any:\n    \"\"\"\n    Fit a logistic regression (binomial) predicting Approved from Female and controls.\n    Returns: statsmodels fitted results object with robust standard errors (HC3).\n    \"\"\"\n    import statsmodels.api as sm\n\n    # Identify control columns present in the transformed dataframe (all columns except the DV and IV)\n    all_cols = list(df.columns)\n    if 'Approved' not in all_cols or 'Female' not in all_cols:\n        raise ValueError(\"Dataframe must contain 'Approved' and 'Female' columns. Make sure to run the transform function first.\")\n\n    control_cols = [c for c in all_cols if c not in ['Approved', 'Female']]\n\n    # Prepare X and y\n    X = df[['Female'] + control_cols].copy()\n    # Add constant\n    X = sm.add_constant(X, has_constant='add')\n    y = df['Approved']\n\n    # Fit logistic regression (use GLM with binomial family or Logit). We'll use Logit and then get robust covariances.\n    logit = sm.Logit(y, X)\n    result = logit.fit(disp=False)\n\n    # Get robust (heteroskedasticity-consistent) covariance estimates for inference\n    result_robust = result.get_robustcov_results(cov_type='HC3')\n\n    # Return robust results object. Caller can inspect result_robust.summary() or result_robust.params, etc.\n    return result_robust\n"
}

